def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # The repeated marker color is the most common non-background color.
    marker = max((v for v in counts if v != bg), key=lambda v: counts[v])
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker]

    seed = [(r, c) for r in range(h) for c in range(w)
            if grid[r][c] != bg and grid[r][c] != marker]
    r0, r1 = min(r for r, c in seed), max(r for r, c in seed)
    c0, c1 = min(c for r, c in seed), max(c for r, c in seed)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    shape = [(r - ar, c - ac, grid[r][c])
             for r in range(r0, r1 + 1)
             for c in range(c0, c1 + 1)
             if grid[r][c] != bg]

    out = [row[:] for row in grid]
    for mr, mc in markers:
        for dr, dc, val in shape:
            rr, cc = mr + dr, mc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = val
    return out
